A: Placing Marbles

 それぞれの文字が1 か0 かを判定して1 の数を数えればよいです．マスの数は高々3 つなので，for 文を使わなくて
も簡単に実装できます．

#include <iostream>

#include <string>

using namespace std;

int ans;

string s;

int main(){

    cin >> s;

    if(s[0]=='1') ans++;
    if(s[1]=='1') ans++;

    if(s[2]=='1') ans++;

    cout << ans << endl;

}





